// 겪어 보기 · 🧑 어른 버전: 아는 것이 없다고 보고 처음부터 설명.
// 용어는 처음 나올 때 풀어 쓰고, 숫자와 표, 흔한 오해, 이 계산의 한계를 함께 적음.
window.RAUM_LAB_FULL = (K) => {
  const { D, F, c1, START, END, at, NAMES, STORES, label, pct, dir, md, ym, card, rows, table, note, graph, profit, stat, target, flip, long } = K;
  const company = (s) => `${NAMES[s][0]} ${NAMES[s][2]}`;
  // 흔한 오해: [오해, 실제]
  const myths = (list) => card(`<h2>🙋 어른도 자주 헷갈려요</h2>${list.map(([m, t]) => `<div class="myth"><b>“${m}”</b><p>${t}</p></div>`).join("")}`);

  // ---------- ① 가게 실력과 주가 ----------
  const GAPS = [
    { sym: "AMZN", from: "2020-02-19", to: "2020-03-12", why: "이 시기에는 감염병이 퍼지면서 <b>시장 전체</b>가 크게 내렸어요." },
    { sym: "AAPL", from: "2020-02-12", to: "2020-03-23", why: "이 시기에도 <b>시장 전체</b>가 크게 내렸어요. 이익을 내는 회사의 주가도 함께 내릴 수 있어요." },
    { sym: "ZM", from: "2020-10-19", to: "2020-12-31", why: "11월 백신 소식 등으로 ‘앞으로도 이만큼 빨리 자랄까?’ 하는 기대가 달라졌다고 흔히 설명해요. 다만 주가가 움직인 이유를 하나로 확정할 수는 없어요." },
  ];
  const gapPages = GAPS.flatMap(({ sym, from, to, why }) => {
    const a = at(from), b = to === "2020-12-31" ? END : at(to), p = D.prices[sym], drop = Math.round((1 - p[b] / p[a]) * 100);
    const grew = F[sym].now.net / F[sym].prev.net;
    const grewText = grew >= 2 ? `약 ${Math.round(grew)}배가 됐어요` : `${Math.round((grew - 1) * 100)}% 늘었어요`;
    return [
      () => ({
        title: `${company(sym)}의 이익`,
        body: profit(sym, "순이익 (비용과 세금을 빼고 남은 돈)"),
        text: `${NAMES[sym][2]}의 연간 순이익은 ${grewText}.`,
        ask: { key: `gap-${sym}`, q: "이 무렵 주가는 어땠을까요?", opts: ["📈 계속 올랐을 것 같다", "📉 중간에 크게 내렸을 수도 있다", "🤷 이익만으로는 알 수 없다"], reply: () => "먼저 생각해 보는 것으로 충분해요. 실제 주가를 같이 볼게요." },
      }),
      () => ({
        title: `${company(sym)}의 주가`,
        body: card(`<h2>2020년 주가</h2>${graph([{ ys: p.slice(START, END + 1), color: "#2f6fe4" }], { mark: [a - START, b - START], left: "1월", right: "12월" })}${rows([[`${md(from)} → ${md(to)}`, `<span class="down">▼ ${drop}%</span>`], ["2020년 1년 전체", `<span class="${dir(p[END] / p[START])}">${pct(p[END] / p[START])}</span>`]])}`) + card(`<p>${why}</p><p class="small">⏰ 연간 이익은 회계연도가 끝난 뒤에 발표돼요. 노란 기간에는 이 숫자를 아직 다 알 수 없었어요.</p>`),
        text: `노란 기간에 주가는 ${drop}% 내렸어요. 연간 이익이 늘어난 해에도 주가는 크게 내릴 수 있어요.`,
      }),
    ];
  });
  const GAP = [
    () => ({
      title: "회사와 주가는 따로 봐요",
      body: card(rows([["📄 주식", "회사 소유권의 한 조각"], ["🏷️ 주가", "지금 그 한 조각이 거래되는 값"], ["🏪 순이익", "회사가 1년 동안 벌고 남긴 돈"]])) + myths([["1주 값이 싼 회사가 싼 회사다", "회사 전체의 값(시가총액)은 <b>주가 × 주식 수</b>예요. 1주가 1만 원이어도 주식 수가 많으면 1주 100만 원인 회사보다 전체 값이 클 수 있어요."]]),
      text: "주가는 회사 실력 그 자체가 아니라, 사람들이 사고팔며 정한 값이에요. 실제 회사 세 곳에서 둘이 어긋난 기간을 살펴봐요.",
    }),
    ...gapPages,
    () => ({
      title: "알게 된 것",
      body: card(rows([["📈 이익이 늘어난 해에도", "주가는 내릴 수 있어요"], ["📉 주가가 내렸다고", "회사가 꼭 나빠진 건 아니에요"], ["⚠️ 하지만", "정말 나빠졌을 수도 있어요"]])) + note("이 세 회사의 기간은 차이가 잘 보이도록 일부러 골랐어요. 내린 주가가 늘 다시 오르는 것은 아니에요."),
      text: "주가가 크게 움직이면 먼저 확인해요. 회사의 장사도 달라졌나요, 아니면 사람들의 기대나 시장 분위기가 달라졌나요?",
    }),
  ];

  // ---------- ② 싼 주식, 비싼 주식 ----------
  const BASE = { e: 10, v: 200 };
  const QUAD = [
    { t: "주가 하락, 이익은 그대로", e: 10, v: 140, msg: "같은 이익을 내는 회사를 더 낮은 PER로 살 수 있게 됐어요. 이익이 앞으로도 유지된다면 전보다 싸졌다고 볼 수 있어요." },
    { t: "주가는 내렸는데 이익이 더 많이 감소", e: 5, v: 140, msg: "값은 내렸지만 PER은 오히려 높아졌어요. 값이 내렸다고 싸진 것이 아닐 수 있어요." },
    { t: "주가는 올랐는데 이익이 더 많이 증가", e: 20, v: 300, msg: "값은 올랐지만 PER은 낮아졌어요. 올랐어도 전보다 싸졌을 수 있어요." },
    { t: "주가 상승, 이익은 그대로", e: 10, v: 300, msg: "이익은 같은데 PER만 높아졌어요. 기대가 더 커졌다는 뜻일 수 있고, 기대에 못 미치면 값이 내릴 수 있어요." },
  ];
  const times = (o) => Math.round(o.v / o.e);
  const quadCard = (q) => card(`${table(["", "전", "후"], [["연간 순이익", `${BASE.e}`, `<b>${q.e}</b>`], ["회사 전체 값", `${BASE.v}`, `<b>${q.v}</b>`]])}<p class="small">연습용으로 만든 예시 숫자예요.</p>`);
  const peAt = (sym) => D.prices[sym][START] / F[sym].eps;
  const multi = (sym) => (D.prices[sym][END] / D.prices[sym][START]) / (F[sym].now.net / F[sym].prev.net);
  const CHEAP = [
    () => ({
      title: "PER: 이익의 몇 배?",
      body: card(rows([["연간 순이익", "10"], ["회사 전체 값 (시가총액)", "200"], ["PER = 시가총액 ÷ 순이익", "20배"]])) + card(`<p>1주 기준으로는 <b>주가 ÷ 주당순이익(EPS)</b>으로 계산해요. 이렇게 회사의 실력에 비해 값이 어느 정도인지 재는 것을 <b>밸류에이션</b>이라고 해요.</p>`),
      text: "주가만 보고는 싼지 비싼지 알 수 없어요. 이익에 비해 몇 배의 값을 내는지 봐요.",
    }),
    ...QUAD.map((q, i) => () => ({
      title: q.t, body: quadCard(q),
      text: `처음 PER은 ${times(BASE)}배였어요. 바뀐 뒤에는 어떨까요?`,
      ask: { key: `quad-${i}`, q: "PER은 어떻게 됐을까요?", opts: ["▲ 높아졌을 것 같다", "▼ 낮아졌을 것 같다"], reply: () => `${q.v} ÷ ${q.e} = <b>${times(q)}배</b>. 20배에서 ${times(q) > times(BASE) ? "높아졌어요" : "낮아졌어요"}.<br>${q.msg}` },
    })),
    () => ({
      title: "실제 기록: 둘 다 올랐는데",
      body: card(table(["2020년", "주가", "순이익", "배수"], ["AMZN", "AAPL"].map((s) => [company(s), pct(D.prices[s][END] / D.prices[s][START]), pct(F[s].now.net / F[s].prev.net), multi(s) >= 1.1 ? "<b>많이 커짐</b>" : "<b>조금 작아짐</b>"]))) + note("주가는 2020년 1월 → 12월, 이익은 회계연도끼리 비교한 대략의 계산이에요(주식 수 변화는 뺐어요). 이익은 나중에 발표된 숫자예요."),
      text: "아마존과 애플은 주가가 비슷하게 올랐어요. 하지만 아마존은 이익이 더 많이 늘어 배수가 조금 작아졌고, 애플은 이익이 조금 늘어 배수가 많이 커졌어요.",
    }),
    () => ({
      title: "PER이 낮으면 안전할까?",
      body: card(`<h2>2020년 1월 시점</h2>${table(["회사", "당시 PER", "2020년 주가", "다음 성적"], ["AAL", "CCL"].map((s) => [company(s), `약 ${Math.round(peAt(s))}배`, `<span class="${dir(D.prices[s][END] / D.prices[s][START])}">${pct(D.prices[s][END] / D.prices[s][START])}</span>`, "적자"]))}<p>PER이 낮아 싸 보였지만, 여행이 멈추면서 <b>이익이 적자로 바뀌었어요.</b> 적자인 회사는 PER을 계산할 수 없어요.</p>`) + note("이런 감염병은 미리 알기 어려웠어요. PER이 낮으면 늘 나쁘고 높으면 늘 좋다는 뜻도 아니에요."),
      text: "PER은 보통 이미 지나간 이익으로 계산해요. 앞으로의 이익이 달라지면, 싸 보이던 값이 싸지 않았던 것이 될 수 있어요.",
    }),
    () => ({
      title: "확인할 네 가지 질문",
      body: card(rows([["1️⃣ 왜", "주가가 왜 바뀌었나?"], ["2️⃣ 실력", "이익·빚·현금은 어떻게 됐나?"], ["3️⃣ 배수", "그 회사의 과거, 비슷한 회사와 비교하면?"], ["4️⃣ 반대로", "내 생각이 틀리면 어떻게 되나?"]])) + myths([
        ["많이 내렸으니 싸다", "내리기 전 값은 기준이 아니에요. 이익이 더 많이 줄었다면 내린 뒤에도 비쌀 수 있어요."],
        ["많이 올랐으니 비싸다", "이익이 더 빨리 늘었다면 올랐어도 배수는 낮아졌을 수 있어요."],
        ["PER 숫자 하나면 판단할 수 있다", "업종마다 보통 수준이 다르고, 일시적인 이익이 섞이면 PER이 낮게 보일 수 있어요."],
      ]),
      text: "네 가지를 다 확인해도 확실히 알 수는 없어요. 전문가끼리도 판단이 달라요. 그래서 같은 값에 사는 사람과 파는 사람이 함께 있어요.",
    }),
  ];

  // ---------- ③ 개별 주식과 S&P 500 ----------
  const LIMITS = [9, 7, 5];
  const BASKET = [
    () => ({ title: "개별 주식과 인덱스", body: card(rows([["개별 주식", "회사 한 곳의 소유권 조각"], ["S&P 500", "미국 대표 기업 약 500곳의 주가를 모아 만든 <b>지수(인덱스)</b>"], ["인덱스 ETF", "지수를 따라가도록 만든 펀드. 주식처럼 사고팔아요 (예: SPY)"]])) + note("S&P 500은 모든 회사를 똑같이 담지 않아요. 시가총액이 큰 회사의 비중이 더 커요."), text: "지수는 숫자라서 직접 살 수 없고, 지수를 따라가는 상품을 사요. 회사 한 곳을 가질 때와 어떻게 다른지 같은 해를 두 번 걸어 봐요." }),
    () => ({ title: "회사 하나 고르기", body: "", text: "2020년에 S&P 500 ETF와 나란히 비교할 회사를 하나 골라요.", ask: { key: "shop", q: "어느 회사와 비교할까요?", opts: STORES.map(company), reply: (i) => `${NAMES[STORES[i]][2]}을(를) 골랐어요.` } }),
    () => ({ title: "먼저 감당할 선 정하기", body: card(`<p>100만 원을 넣었다고 생각해도 좋아요. 이 체험에서는 <b>10</b>으로 시작해요.</p>`), text: "결과를 보기 전에 정해요. 1년 동안 얼마까지 줄어도 계획을 바꾸지 않을 수 있을까요?", ask: { key: "limit", q: "10이 얼마까지 줄어도 괜찮나요?", opts: LIMITS.map((n) => `${n}까지 (−${(10 - n) * 10}%)`), reply: (i) => `${LIMITS[i]}까지라고 정했어요. 실제로 줄어드는 것을 볼 때의 마음은 상상할 때와 다를 수 있어요.` } }),
    (P) => {
      const sym = STORES[P.shop ?? 0], limit = LIMITS[P.limit ?? 1], a = stat(sym), b = stat("SPY");
      const over = (x) => (x.low < limit ? `정한 ${limit}보다 더 내려갔어요` : `정한 ${limit} 아래로는 내려가지 않았어요`);
      return {
        title: "같은 2020년, 두 길",
        body: card(`${graph([{ ys: a.ys, color: "#e8590c" }, { ys: b.ys, color: "#1f9e7f" }], { base: limit, left: "1월", right: "12월" })}<p class="legend"><span style="color:#e8590c">━ ${company(sym)}</span> <span style="color:#1f9e7f">━ S&amp;P 500 ETF</span> <span class="muted">┅ 내가 정한 선</span></p>${table(["10으로 시작", NAMES[sym][2], "ETF"], [["연말", c1(a.end), c1(b.end)], ["가장 낮을 때", c1(a.low), c1(b.low)], ["하루 5% 넘게 움직인 날", `${a.wild}일`, `${b.wild}일`]])}`) + card(`<p>${NAMES[sym][2]}: ${over(a)}.<br>S&amp;P 500 ETF: ${over(b)}.</p><p class="small">연말 결과만 보지 말고, 가는 동안 얼마나 흔들렸는지도 함께 봐요.</p>`),
        text: `10이 가장 낮을 때 ${NAMES[sym][2]}은(는) ${c1(a.low)}, ETF는 ${c1(b.low)}였어요.`,
      };
    },
    () => {
      const list = [...STORES, "SPY"].map((s) => ({ s, ...stat(s) })).sort((x, y) => y.end - x.end);
      return { title: "일곱 회사를 모두 보면", body: card(table(["10으로 시작", "연말", "최저", "5%↑ 움직인 날"], list.map((x) => [x.s === "SPY" ? "<b>🧺 S&amp;P 500 ETF</b>" : company(x.s), c1(x.end), c1(x.low), `${x.wild}일`]))) + note("이 일곱 곳은 이 앱에서 고른 유명한 회사예요. 모든 회사를 대표하지 않고, 2020년 한 해의 결과예요."), text: "ETF보다 훨씬 많이 오른 회사도, 훨씬 많이 내린 회사도 있어요. 어느 쪽이 될지는 미리 알기 어려워요." };
    },
    () => ({
      title: "좋은 점과 아쉬운 점",
      body: card(`<h2>개별 주식</h2><p>👍 잘 고르면 지수보다 훨씬 많이 오를 수 있어요.<br>👎 회사 한 곳의 문제로 크게 잃을 수 있고, 회사를 계속 살펴봐야 해요.</p>`) + card(`<h2>인덱스 ETF</h2><p>👍 여러 회사에 나눠 담겨 한 회사의 영향이 작아요.<br>👎 시장 전체가 내리면 <b>함께 크게 내려요.</b> 가장 많이 오른 회사만큼 오르기는 어렵고, 운용 비용(보수)이 있어요.</p>`) + myths([
        ["S&P 500에 넣으면 원금은 안전하다", "원금이 보장되지 않아요. 앞에서 본 2020년 봄처럼 크게 내릴 수 있어요."],
        ["한국에서 사면 지수만큼 그대로 번다", "원화로 바꿔 보면 <b>환율</b>에 따라 결과가 달라져요(환헤지 상품은 다를 수 있어요). 보수와 세금도 상품과 계좌에 따라 달라요."],
        ["이름에 S&P 500이 있으면 다 같은 상품이다", "<b>레버리지·인버스</b> 상품은 하루 움직임의 몇 배 또는 반대를 따라가도록 만든 거예요. 오래 가지면 지수의 몇 배와 크게 달라질 수 있어요. 사기 전에 상품 설명서를 확인해요."],
      ]),
      text: "인덱스는 안전 상자가 아니라, 한 곳에 몰지 않는 방법이에요.",
    }),
  ];

  // ---------- ④ 언제 팔까 ----------
  const RULES = ["💰 모두 팔기", "✂️ 절반만 팔기", "🌳 그대로 두기"];
  const SELL = [
    { set: "h2023", sym: "NVDA", name: "🎮 엔비디아 · 2023년 상반기", short: "엔비디아", msg: "목표에서 판 뒤에도 훨씬 더 올랐어요. 이 기간에는 그대로 둔 쪽이 많았어요." },
    { set: "h2021", sym: "TSLA", name: "🚗 테슬라 · 2021년 1분기", short: "테슬라", msg: "목표를 넘긴 뒤 다시 내려왔어요. 이 기간에는 판 쪽이 많았어요." },
    { set: "2020", sym: "ZM", name: "💻 줌 · 2020년", short: "줌", msg: "그대로 두면 연말에 훨씬 많았지만, 가장 높을 때보다는 크게 내려왔어요. 가장 높은 날은 지나고 나서야 알 수 있어요." },
    { set: "2020", sym: "CCL", name: "🚢 카니발 · 2020년", short: "카니발", msg: "목표에 한 번도 닿지 않았어요. ‘오르면 판다’는 약속만 있으면, 내릴 때 무엇을 할지는 정하지 않은 거예요." },
  ];
  const sellPage = (c) => (P) => {
    const t = target(c.set, c.sym), mine = P.rule ?? 2;
    return {
      title: c.name,
      body: card(`${graph([{ ys: t.ys, color: "#2f6fe4" }], { base: 12, left: ym(t.d[0]), right: ym(t.d.at(-1)) })}<p class="legend muted">┅ 목표 12 (+20%) · ${t.hit < 0 ? "목표에 닿지 않았어요" : `${md(t.d[t.hit])}에 처음 닿았어요`} · 가장 높을 때 ${c1(t.top)}</p>${rows(RULES.map((r, i) => [`${r}${i === mine ? " <em>내 약속</em>" : ""}`, c1(t.out[i]), i === mine ? "mine" : ""]))}`),
      text: c.msg,
    };
  };
  const FLIPS = [["h2000", "QQQ", "🧺 미국 기술주 ETF(QQQ) · 2000년 상반기"], ["h2009", "GS", "🏦 골드만삭스 · 2009년 상반기"], ["2020", "CCL", "🚢 카니발 · 2020년"], ["h2008", "AIG", "☂️ AIG · 2008년 가을"]];
  const SELLING = [
    () => ({ title: "파는 것은 더 어려워요", body: card(`<p>흔히 <b>“파는 건 예술”</b>이라고 말해요. 언제 팔아야 하는지 늘 맞는 공식이 없다는 뜻이에요.</p>`), text: "사는 것만큼, 어쩌면 더 어려운 것이 파는 결정이에요. 실제 기록으로 여러 번 겪어 봐요." }),
    () => ({ title: "먼저 약속 정하기", body: card(`<p>10으로 사고, 목표는 <b>12 (20% 상승)</b>예요.</p>`), text: "목표에 닿으면 어떻게 할지 먼저 정해요. 네 가지 사례에 같은 약속을 적용해 볼 거예요.", ask: { key: "rule", q: "목표에 닿으면?", opts: RULES, reply: (i) => `약속: <b>${RULES[i]}</b>. 맞고 틀린 답은 없어요.` } }),
    ...SELL.map(sellPage),
    () => ({
      title: "네 사례를 나란히",
      body: card(table(["회사", "모두 팔기", "절반", "두기"], SELL.map((c) => [c.short, ...target(c.set, c.sym).out.map(c1)]))) + note("서로 다른 결과를 보여 주려고 일부러 고른 네 기간이에요. 어느 약속이 더 자주 이기는지는 이것으로 알 수 없어요. 세금·수수료는 빼고, 판 돈은 현금으로 두었다고 계산했어요."),
      text: "어떤 때는 파는 쪽이, 어떤 때는 두는 쪽이 더 많았어요. 늘 이기는 약속은 없었어요.",
    }),
    () => ({
      title: "자주 사고팔면 나을까?",
      body: card(`<p>규칙: <b>마지막으로 산 값보다 10% 내리면 모두 팔고, 판 값보다 10% 오르면 다시 사기</b></p>${table(["사례", "그대로", "사고팔기", "거래"], FLIPS.map(([set, sym, name]) => { const f = flip(set, sym); return [name, c1(f.hold), c1(f.traded), `${f.n}번`]; }))}<p>🚢 ☂️ 크게 내려간 사례에서는 판 쪽이 훨씬 덜 잃었어요. 거래 1번은 <b>한 번 팔고 다시 사지 않았다</b>는 뜻이에요.<br>🧺 🏦 오르내리거나 다시 오른 사례에서는 사고판 쪽이 더 적었어요. <b>싸게 팔고 더 비싸게 다시 사게 됐기 때문이에요.</b></p>`) + note("일부러 고른 기간이에요. 수수료·세금을 넣으면 거래할 때마다 결과가 더 줄 수 있어요."),
      text: "오래 가진다고 늘 좋은 것도 아니고, 자주 사고판다고 늘 좋은 것도 아니에요.",
    }),
    () => ({
      title: "목표에 닿으면 = 다시 확인할 때",
      body: card(`<p>목표 값은 <b>반드시 팔라는 신호가 아니라, 다시 살펴보라는 알림</b>으로 쓸 수 있어요.</p>${rows([["1️⃣ 처음 이유", "산 이유가 아직 맞나?"], ["2️⃣ 값", "실력에 비해 너무 높아지진 않았나?"], ["3️⃣ 쓸 돈", "곧 써야 하는 돈인가?"], ["4️⃣ 몰림", "한 회사가 내 돈에서 너무 커졌나?"]])}`) + card(`<p>답에 따라 <b>그대로 두기 · 일부 팔기 · 모두 팔기</b>를 고를 수 있어요. 목표에 못 닿아도 <b>산 이유가 틀렸다면</b> 다시 정해야 해요.</p>`) + myths([["본전만 오면 팔겠다", "내가 산 값은 회사의 실력이나 앞으로의 주가와 관계가 없어요. ‘지금 처음 본다면 이 값에 살까?’라고 물어보면 도움이 돼요."]]),
      text: "팔지 말지는 값만 보지 말고 네 가지를 확인하고 정해요.",
    }),
    () => ({ title: "사기 전에 적어 두기", body: card(`<p>값이 크게 움직이면 마음이 흔들려요. 그래서 <b>사기 전에</b> 이유와 다시 확인할 때를 적어 두면 도움이 돼요.</p>`), text: "마지막으로, 언제 다시 확인할지 하나 골라 봐요.", ask: { key: "plan", q: "어느 때 꼭 다시 확인할까요?", opts: ["🏪 회사의 장사가 달라졌을 때", "🎯 목표 값에 닿았을 때", "🗓️ 정해 둔 날이 됐을 때"], reply: () => "좋아요. 셋 다 확인할 때로 정해도 돼요. 가족과 함께 ‘왜 샀는지, 언제 다시 볼지’를 적어 보세요." } }),
  ];

  // ---------- ⑤ 10년의 기다림 ----------
  const yearTable = (L) => table(["해", "연말", "그해 최저"], L.years.map((y) => [`${y.y}`, `<span class="${dir(y.end / 10)}">${c1(y.end)}</span>`, c1(y.low)]));
  const longGraph = (L) => graph([{ ys: L.ys, color: "#1f9e7f" }], { base: 10, left: `${L.from}년`, right: `${L.to}년` });
  const longNote = "10으로 시작해 한 번 사고 그대로 둔 계산이에요. 배당을 반영한 수정 종가이고, 세금·수수료·환율·물가는 넣지 않았어요.";
  const spy = (id, title, text) => () => { const L = long(id); return { title, body: card(longGraph(L) + yearTable(L)) + note(longNote), text: text(L) }; };
  const WAIT = [
    () => ({
      title: "‘장기투자’는 얼마나 길까?",
      body: card(`<p>S&amp;P 500 ETF(SPY)를 <b>2007년 첫 거래일</b>에 10만큼 샀다고 해 봐요. 그리고 10년 동안 팔지 않아요.</p>`),
      text: "며칠이나 1년이 아니라 10년이에요. 가는 길을 보기 전에 먼저 생각해 봐요.",
      ask: { key: "bear", q: "중간에 10이 어디까지 줄어도 버틸 수 있을까요?", opts: ["8까지", "6까지", "5 아래도"], reply: () => `실제로는 가장 낮은 날 <b>${c1(long("spy2007").low)}</b>까지 내려갔어요. 그때는 다시 오를지 알 수 없었어요.` },
    }),
    spy("spy2007", "2007년에 시작한 10년", (L) => `2009년에는 ${c1(L.low)}까지 줄었어요. 10년 뒤에는 ${c1(L.end)}예요. 처음 값 아래에서 여러 해를 보냈어요.`),
    spy("spy2000", "2000년에 시작한 10년", (L) => `똑같은 상품인데 시작한 해가 다르면, 10년 뒤에도 ${c1(L.end)}로 처음보다 적었어요. ‘10년이면 반드시 오른다’는 말은 맞지 않아요.`),
    () => {
      const a = long("aig2007"), b = long("aapl2007");
      return { title: "회사 하나로 10년", body: card(`<h2>☂️ AIG (보험)</h2>${longGraph(a)}`) + card(`<h2>🍎 애플</h2>${longGraph(b)}`) + card(table(["2007~2016", "10년 뒤", "가장 낮을 때"], [["☂️ AIG", c1(a.end), c1(a.low)], ["🍎 애플", c1(b.end), c1(b.low)]])) + note("AIG는 2008년 금융위기 때 큰 손실로 미국 정부의 지원을 받은 회사예요. 두 회사는 결과를 알고 고른 것이라, 2007년에 이런 결과를 알 수 있었다는 뜻이 아니에요. " + longNote), text: "같은 10년 동안 한 회사는 대부분을 잃고 돌아오지 못했고, 한 회사는 열 배가 넘게 커졌어요." };
    },
    () => ({
      title: "내려간 만큼 오르면 본전일까?",
      body: card(table(["이만큼 내리면", "본전까지 필요한 상승"], [10, 30, 50, 90].map((d) => [`−${d}%`, `+${Math.round((1 / (1 - d / 100) - 1) * 100)}%`]))) + card(`<p>10이 5가 되면 −50%예요. 5가 다시 10이 되려면 <b>+100%</b>가 필요해요.</p>`),
      text: "크게 잃을수록 되돌아오는 데 훨씬 큰 상승이 필요해요.",
    }),
    () => ({
      title: "기다리기 전에 확인할 것",
      body: card(rows([["🗓️ 언제 쓸 돈", "곧 쓸 돈은 크게 내려도 기다릴 수 없어요"], ["🧺 몰림", "한 회사는 돌아오지 못할 수 있어요"], ["📉 감당", "반 가까이 줄어드는 해가 와도 괜찮은가"], ["🔁 이유", "회사나 상품이 처음 이유와 아직 맞나"]])) + myths([
        ["오래 들고 있으면 결국 오른다", "회사 하나는 끝내 회복하지 못할 수 있어요. 지수도 10년 뒤에 처음보다 적었던 때가 있어요."],
        ["지난 10년 성적이 좋았으니 앞으로도 좋다", "시작한 해에 따라 10년 결과가 크게 달랐어요. 지나간 결과는 앞으로를 약속하지 않아요."],
      ]),
      text: "기다림은 도움이 될 수 있지만, 결과를 약속하지는 않아요.",
    }),
  ];

  return { lab1: GAP, lab2: CHEAP, lab3: BASKET, lab4: SELLING, lab5: WAIT };
};
